"""Extract and render reports generated by browser-smoke.cjs for visual QA."""
from pathlib import Path
from pypdf import PdfReader
import pypdfium2 as pdfium

directory = Path(__file__).resolve().parents[2] / '.next-validation' / 'desktop-qa'
for kind in ['transcripcion', 'analisis']:
    source = next(directory.glob(f'*_{kind}.pdf'))
    reader = PdfReader(source)
    text = '\n'.join(page.extract_text() for page in reader.pages)
    assert 'MeetPulse' in text
    assert 'Estudio Norte' in text
    if kind == 'transcripcion':
        assert 'Segmento 129' in text, 'Transcript tail was lost during paginated export'
        assert 'Ajuste sin guardar' not in text
    else:
        assert 'Ajuste sin guardar' in text, 'Analysis export did not use the live editor snapshot'
        assert 'Responsable' in text and 'Viernes' in text
        assert any(page.get('/Annots') for page in reader.pages), 'Analysis link was lost'
    document = pdfium.PdfDocument(str(source))
    for index in range(len(document)):
        page = document[index]
        textpage = page.get_textpage()
        searcher = textpage.search(f'{index + 1} / {len(document)}')
        match = searcher.get_next()
        assert match is not None, f'Missing page number on page {index + 1}'
        assert textpage.get_charbox(match[0])[3] < 60, f'Footer is not at the bottom on page {index + 1}'
        page.render(scale=1.3).to_pil().save(directory / f'{kind}-{index + 1}.png')
        page.close()
    document.close()
    print(f'{kind}: {len(reader.pages)} pages, {len(text)} characters, rendered and verified')

long_analysis = directory.parent / 'template-fixture' / 'analysis-long.pdf'
if long_analysis.exists():
    document = pdfium.PdfDocument(str(long_analysis))
    assert len(document) > 5
    text = ''
    for index in range(len(document)):
        page = document[index]
        textpage = page.get_textpage()
        text += textpage.get_text_range()
        match = textpage.search(f'{index + 1} / {len(document)}').get_next()
        assert match is not None and textpage.get_charbox(match[0])[3] < 60
        if index in (0, len(document) // 2, len(document) - 1):
            page.render(scale=1.3).to_pil().save(long_analysis.parent / f'analysis-page-{index + 1}.png')
        page.close()
    assert 'Decisión 35' in text and 'Equipo 35' in text
    print(f'long analysis: {len(document)} pages, all page numbers and final table verified')
    document.close()
